from pathlib import Path
import json,re
from datetime import datetime,timezone,timedelta
root=Path(__file__).parent
def read(n):
 s=(root/n).read_text(encoding='utf-8-sig')
 try:return json.loads(s)
 except json.JSONDecodeError:return json.loads(next(x for x in s.splitlines() if x.startswith('{')))
m=read('manifest.json');v=read('verify.json');d=read('deployment.json');samples=[]
assert len(m['rows'])==len(v['rows'])==5 and v['ok']
for r in m['rows']:
 for mode in ['desktop','mobile']:
  records=read(r['slug']+'-'+mode+'-qa.json')
  assert [x['slide'] for x in records]==[1,2,3,4]
  for x in records:
   assert x['id']==r['id'] and x['mode']==mode and x['align']=='center' and not x['overflow']
   assert len(x['active'])==1 and x['active'][0]['loaded'] and x['active'][0]['alt']==x['expected_alt']
   assert x['visible_count']==1 and x['dots']==4 and x['arrows']==2 and int(x['bold'])>=600
   assert x['viewport']==(390 if mode=='mobile' else 1440)
  samples+=records;assert read(r['slug']+'-'+mode+'-controls.json')['pass']
assert len(samples)==40 and len(list(root.glob('*-controls.json')))==10
for n,k in [('apply.json','ok'),('rollback-preview.json','ok'),('public-qa.json','pass'),('preservation-qa.json','pass'),('visual-review.json','pass')]:assert read(n)[k]
assert sum(len(x['media']) for x in v['rows'])==20
assert len(read('public-qa.json')['rows'])==10 and len(read('public-qa.json')['media'])==20
assert (root/'haiti-published-proof.png').exists()
(root/'browser-qa.json').write_text(json.dumps({'pass':True,'desktop':'1440x1000','mobile':'390x844','next_previous_and_dots_passed':10,'samples':samples},ensure_ascii=False,indent=2),encoding='utf-8')
now=datetime.now(timezone(timedelta(hours=3)));stamp=now.strftime('%Y-%m-%d %H:%M');date=now.strftime('%Y-%m-%d')
commit=d['commit'];names=', '.join(r['name'] for r in m['rows']);oldmedia=sum(r['old_media_preserved'] for r in read('preservation-qa.json')['rows'])
lines=['---','type: work-log','project_id: shustrik-maps-seo','status: completed','date: '+date,'market: USA','language: English','---','','# Пять следующих STL опубликованы и проверены','',names+'. Завершено '+stamp+' МСК по прямому поручению «делай».','','## Выбор и семантика','','Журналы и свежий live inventory сверены; у пяти выбранных товаров не было собственных AI-слайдеров, у каждого стояла единственная ссылка на общий HTML-блок9586. Предыдущая партия Eritrea–Papua New Guinea и более ранние завершённые партии исключены. Беларусь не рассматривается. [[selection.json]] / [[baseline.json]].','','Google / English / USA: сохранённое ядро05.10 не содержит точных пяти STL-кластеров. Новые группы редакционные, frequency/rank=null. Публичный английский поиск проверяет intent, а не частотности или Google-US позиции. Haiti отделён от Dominican Republic; Bermuda — островная территория с морским рельефом вокруг архипелага. Бесплатный Bhutan STL, локальные рельефы, обычные карты и laser SVG не приравниваются к платному whole-place STL. Для Bermuda независимое точное платное STL-предложение не установлено по выполненным запросам. [[Intent Review]] / [[semantic-review.json]] / [[Page Briefs]].','','## Публикация','','Изменены только SEO title/meta и выбранная иллюстрационная вставка Description: ссылка на общий блок9586 заменена собственным native Woodmart carousel. Все прежние vc_column_text/main prose сохранены дословно. H1, URL, excerpt/specs, цены, files/downloads, thumbnail, верхняя галерея и прочие productmeta защищены. Общий блок9586 не изменён, старые media не удалялись: '+str(oldmedia)+' прежних изображений сохранены по ID/title/URL. [[preservation-qa.json]] / [[after.json]].','','20 отдельных native ImageGen вызовов по собственным географическим референсам; каждый результат осмотрен. Сцены: ivory plastic desktop на сплошной walnut-подложке; небольшая картина; подарок в kraft-коробке; большая инсталляция из серого бетона. Настольные рельефы целиком опираются на цельную подложку, включая острова Haiti/Belize. Bermuda сохраняет квадратный bathymetric tile, мелководную платформу, островную цепь и подводные склоны; вся плитка на сплошной подложке. Сохранены20 оригиналов PNG,10 собственных референсов и prompts. Точное совпадение с mesh не заявляется. [[generation-jobs.json]] / [[generated-registry.json]] / [[visual-review.json]].','','20 настоящих JPEG1500×1000 с описательными title/alt и явной AI-концепт маркировкой. Один слайд desktop/mobile, две ручные стрелки внутри доступной области блока (carousel_arrows_position=together), четыре точки, autoplay=no. Под слайдером только жирная центрованная **AI-generated application concepts.** [[uploaded-media.json]].','','Все пять listings указывают base=closed. Mesh/STL archives/readiness не проверялись; прежние claims сохранены, новые не добавлены. Подложки, рамы, упаковка и concrete fabrication — отдельная проектная работа; коммерческий концепт не расширяет лицензию.','','## Товары','','| Товар | ID | Media IDs | URL |','|---|---:|---|---|']
for r in v['rows']:
 name=next(x['name'] for x in m['rows'] if x['id']==r['id'])
 lines.append('| '+name+' | '+str(r['id'])+' | '+', '.join(str(a['id']) for a in r['media'])+' | '+r['url']+' |')
lines+=['','## Доставка, QA и runtime','',f'GitHub-first: SSH origin/main; starting HEAD9ec16eb; fetch/prune, upstream0:0, прежние dirty/untracked сохранены. Source {commit} committed/pushed, remote main совпал. Точный архив SHA256 {d["archive_sha256"]} local/VPS совпал; source доставлен в {d["wp_source"]} внешнего WordPress https://shustrik-maps.com. PHP lint/preview5/5 прошли. Apply выполнен ровно один раз с уникальными backup/journal и проверкой параллельных изменений. [[deployment.json]] / [[apply.json]].','','DB5/5: точные SEO/Description, защищённые данные, before-backup совпал с baseline, journal status=published. Media20/20: SHA256, image/jpeg,1500×1000,title/alt/caption. Public HTTP10/10: обычный и query URL200, точные SEO, H1/self-canonical/indexability/Product schema/CTA, четыре новых media, краткая подпись, отсутствие raw shortcode. Media20/20 HTTP200/image/jpeg. Query не доказывает bypass cache. [[verify.json]] / [[backup-export.json]] / [[public-qa.json]].','','Browser40/40: четыре слайда каждого товара на1440×1000 и390×844. Один активный/видимый слайд с загруженным изображением и верным alt; две стрелки, четыре точки, caption center/font-weight≥600; overflow нет. На всех10 видах Next/Previous/first&last dots прошли. Сохранены10 screenshots и proof. [[browser-qa.json]] / [[haiti-published-proof.png]].','','WireGuard SSH vpsadmin@10.66.66.1 и sudo Docker доступны; сначала проверены сервер/docker ps, затем target WP/DB. Running,RestartCount0,StartedAt и ports before/after совпали: WP127.0.0.1:8083,DB без published ports. Контейнеры не перестраивались и не перезапускались; local runtime не менялся; secrets/.env не читались. [[runtime-before.txt]] / [[runtime-after.txt]].','','## Откат','',f'Guarded rollback-preview5/5 прошёл. Backup _shustrik_five_more_country_stl_slider_backup_20261007_ID; journal _shustrik_five_more_country_stl_slider_media_20261007_ID. Перед откатом: sudo -n docker exec shustrik-maps-wordpress-1 php {d["wp_source"]}/release.php --rollback-preview; затем --rollback только при отсутствии drift. Восстанавливаются прежние Description/SEO; old/new media сохраняются. Rollback не выполнялся. Apply неидемпотентен; при неопределённом результате читать journals/backups, слепой повтор запрещён. [[rollback-preview.json]].','','Партия5/5 завершена. P1 analytics/recovery/consent, индекс10.10, yellow/degraded сохранены. Рост позиций/продаж не заявляется. [[../STL Product Update Workflow]].']
(root/'Release Report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
note=f'## Пять следующих STL завершены — {stamp} МСК\n\n{names}: SEO title/meta и20JPEG1500×1000 опубликованы в собственных слайдерах. Один слайд desktop/mobile, ручные стрелки/точки без autoplay; только жирная центрованная AI-подпись. Настольные рельефы полностью на сплошной подложке; острова закреплены. Bermuda сохранён как квадратный морской рельеф. Основные тексты/H1/URL/specs/commerce/верхние галереи и{oldmedia} прежних media сохранены. [[Five More Country STL Sliders 2026-10-07/Release Report]].\n\nSource {commit} pushed и доставлен точным архивом. DB5/5,media20/20,HTTP10/10,browser40/40,guarded rollback-preview прошли. SSH/sudo Docker доступны; WP/DB running/restart0/StartedAt/ports неизменны. Частотности/позиции не измерялись. P1 analytics/recovery/consent,индекс10.10,yellow/degraded сохранены.\n\n'
for n in ['Shustrik Maps SEO - Overview.md','Shustrik Maps SEO - Next Actions.md']:
 p=root.parent/n;parts=p.read_text(encoding='utf-8').split('---',2);assert len(parts)==3
